/// at 0.1, 735 at 0.3, 864 at 0.55; at 4: 984 at 0.55, 1380 at 0.3).
#[cfg(all(gpu_wgpu, target_arch = "wasm32"))]
fn web_g2_share(threads: usize) -> f64 {
