    #[cfg(all(feature = "trace", not(target_arch = "wasm32")))]
    let width = match std::env::var("ZOPRO_MSM_WIDTH") {
        Ok(value) if bases.len() >= 65536 => value.parse().unwrap(),
        _ => width,
    };
