        let mut positions = starts[..bucket_count].to_vec();

        let mut points = vec![LimbPoint::<C::Base>::infinity(); starts[bucket_count]];
        for (base, digits) in bases.iter().zip(digits.chunks(count)) {
            let digit = digits[i];
