            };
            let mut max_groups = 0;
            for m in [
                31usize, 32, 33, 40, 47, 48, 56, 64, 65, 127, 255, 256, 257, 512, 1023, 2048, 32,
                31, 1, 0,
            ] {
                let mut points: Vec<_> = bases[..2 * m]
                    .iter()
                    .copied()
